with.sysid:
{%- assign g = event.alerts[0].kibana.alert.grouping -%}
{%- assign sysid_group = g.sysid -%}
{%- if sysid_group == nil or sysid_group == "" -%}
  {%- assign sysid_group = g["sysid.keyword"] -%}
{%- endif -%}
{%- assign sysid_ctx = event.alerts[0].kibana.alert.context.sysid -%}
{%- assign sysid_params = event.alerts[0].kibana.alert.rule.parameters.sysid -%}
{%- if sysid_group and sysid_group != "" -%}
  {{ sysid_group }}
{%- elsif sysid_ctx and sysid_ctx != "" -%}
  {{ sysid_ctx }}
{%- elsif sysid_params and sysid_params != "" -%}
  {{ sysid_params }}
{%- endif -%}

with.systype:
{%- assign pr = steps.fetch_problem_reports.output.hits.hits[0]._source.systype -%}
{%- assign rh = steps.fetch_repair_history.output.hits.hits[0]._source.systype -%}
{%- if pr and pr != "" -%}
  {{ pr }}
{%- elsif rh and rh != "" -%}
  {{ rh }}
{%- endif -%}

with.input:
SYSTEM_ID: {{ steps.extract_sysid.output.sysid }}
ALERT_RULE: {{ event.rule.name }}
ALERT_REASON: {{ event.alerts[0].kibana.alert.reason }}

PROBLEM_REPORTS_JSON:
${{ steps.fetch_problem_reports.output.hits.hits | map: '_source' | json }}

REPAIR_RECORDS_JSON:
${{ steps.fetch_repair_history.output.hits.hits | map: '_source' | json }}

with.message:
CT Trend Alert: Pre-cursor Events Leading to Shutdown
=====================================================
System ID : {{ steps.extract_sysid.output.sysid }}
Alert Rule : {{ event.rule.name }}
Triggered  : {{ event.alerts[0]["@timestamp"] }}

Problem reports found : {{ steps.fetch_problem_reports.output.hits.total.value }}
Repair records found  : {{ steps.fetch_repair_history.output.hits.total.value }}

── Correlated Problem / Repair Summary ──────────────────────────────

{{ steps.correlate_problems_and_repairs.output.content }}

── Device Manual (ct_device_manuals) ─────────────────────────────────
{%- assign manual = steps.fetch_device_manual.output.hits.hits[0]._source -%}
{%- if manual and manual.manual_id -%}
Title    : {{ manual.title }}
Version  : {{ manual.version }}
Systype  : {{ manual.systype }}
Manual ID: {{ manual.manual_id }}

Overview:
{{ manual.overview }}

Open full manual in Kibana:
https://klggehpoc-eb6d47.kb.us-central1.gcp.elastic.cloud/app/discover#/doc/default_all_data_id/ct_device_manuals?id={{ manual.manual_id }}
{%- else -%}
No matching device manual found in ct_device_manuals for systype "{{ steps.resolve_systype.output.systype }}".
{%- endif -%}

